<script>
$(function(){
 let shiftPage=1,rosterPage=1,shiftTimer=null,rosterTimer=null,editShiftId=null;const modal=bootstrap.Modal.getOrCreateInstance(document.getElementById('shiftModal'));
 HrUi.initSelect2('.shift-select2,.roster-filter-select2');
 const weekPicker=flatpickr('#rosterWeekStart',{dateFormat:'Y-m-d',altInput:true,altFormat:'d-m-Y',allowInput:true,onChange:()=>loadRoster(1)});
 flatpickr('.shift-time',{enableTime:true,noCalendar:true,dateFormat:'H:i',time_24hr:false,allowInput:true});
 function cv(id){return HrUi.selectValue(id)} function setSelect(id,v){HrUi.setSelectValue(id,v);}
 $('.hr-shift-tab').on('click',function(){$('.hr-shift-tab').removeClass('active');$(this).addClass('active');$('.hr-shift-panel').removeClass('active');$('#'+$(this).data('panel')).addClass('active');if($(this).data('panel')==='dutyRosterPanel')loadRoster(rosterPage)});
 function loadShifts(p=1){shiftPage=p;$('#shiftTableContainer').addClass('hr-table-loading');$.get("{{ route('hr.shifts.table') }}",{page:p,search:$('#shiftSearch').val(),status:cv('shiftStatusFilter')}).done(function(html){const container=$('#shiftTableContainer');container.html(html);HrUi.initSelect2(container);}).fail(()=>Swal.fire('Error','Failed to load shifts.','error')).always(()=>$('#shiftTableContainer').removeClass('hr-table-loading'));}
 $('#shiftSearch').on('input',()=>{clearTimeout(shiftTimer);shiftTimer=setTimeout(()=>loadShifts(1),350)});$('#shiftStatusFilter').on('change',()=>loadShifts(1));$('#shiftReset').on('click',function(){$('#shiftSearch').val('');HrUi.resetSelect('shiftStatusFilter');loadShifts(1)});$(document).on('click','#shiftTableContainer .report-page-link:not(.disabled)',function(e){e.preventDefault();const u=new URL(this.href);loadShifts(u.searchParams.get('page')||1)});
 function resetShiftForm(){editShiftId=null;$('#shiftForm')[0].reset();$('#shiftModalTitle').text('Add Shift');$('#shiftSaveText').text('Save Shift');$('#shiftStatus').prop('checked',true);$('#shiftOvernight').prop('checked',false);$('#shiftBreak').val(0);$('#shiftGrace').val(0);$('#shiftSort').val(0);$('.shift-error').text('');}
 $('#addShiftBtn').on('click',()=>{resetShiftForm();modal.show()});
 $(document).on('click','.shift-edit-btn',function(){resetShiftForm();editShiftId=$(this).data('id');const p=JSON.parse(atob($(this).data('payload')));$('#shiftModalTitle').text('Edit Shift');$('#shiftSaveText').text('Update Shift');$('#shiftName').val(p.name);$('#shiftCode').val(p.code);$('#shiftStart').val(p.start_time);$('#shiftEnd').val(p.end_time);$('#shiftBreak').val(p.break_minutes);$('#shiftGrace').val(p.grace_minutes);$('#shiftSort').val(p.sort_order);$('#shiftNotes').val(p.notes);$('#shiftOvernight').prop('checked',!!p.is_overnight);$('#shiftStatus').prop('checked',!!p.status);modal.show();});
 $('#shiftForm').on('submit',function(e){e.preventDefault();const data=$(this).serializeArray();data.push({name:'status',value:$('#shiftStatus').is(':checked')?1:0},{name:'is_overnight',value:$('#shiftOvernight').is(':checked')?1:0});const url=editShiftId?"{{ url('/hr/shifts') }}/"+editShiftId:"{{ route('hr.shifts.store') }}",type=editShiftId?'PUT':'POST';const btn=$('#shiftSaveBtn').prop('disabled',true);$('.shift-error').text('');$.ajax({url,type,data:$.param(data)}).done(res=>{modal.hide();showToast('Saved',res.message);loadShifts(shiftPage)}).fail(xhr=>{const errors=xhr.responseJSON?.errors||{};Object.keys(errors).forEach(k=>$('[data-error="'+k+'"]').text(errors[k][0]));Swal.fire('Could not save',xhr.responseJSON?.message||'Please check the form.','error')}).always(()=>btn.prop('disabled',false));});
 $(document).on('change','.shift-status-toggle',function(){const id=$(this).data('id'),el=this;$.ajax({url:"{{ url('/hr/shifts') }}/"+id+'/status',type:'PATCH',data:{_token:"{{ csrf_token() }}",status:this.checked?1:0}}).done(res=>showToast('Updated',res.message)).fail(xhr=>{el.checked=!el.checked;Swal.fire('Error',xhr.responseJSON?.message||'Failed.','error')})});
 $(document).on('click','.shift-delete-btn',function(){const id=$(this).data('id');Swal.fire({title:'Delete shift?',text:'Assigned shifts cannot be deleted.',icon:'warning',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#c63d3d'}).then(r=>{if(!r.isConfirmed)return;$.ajax({url:"{{ url('/hr/shifts') }}/"+id,type:'DELETE',data:{_token:"{{ csrf_token() }}"}}).done(res=>{showToast('Deleted',res.message);loadShifts(shiftPage)}).fail(xhr=>Swal.fire('Cannot delete',xhr.responseJSON?.message||'Failed.','error'))})});
 function loadRoster(p=1){rosterPage=p;$('#rosterTableContainer').addClass('hr-table-loading');$.get("{{ route('hr.shifts.roster.table') }}",{page:p,week_start:$('#rosterWeekStart').val(),search:$('#rosterSearch').val(),department_id:cv('rosterDepartment')}).done(function(html){const container=$('#rosterTableContainer');container.html(html);HrUi.initSelect2(container);}).fail(()=>Swal.fire('Error','Failed to load duty roster.','error')).always(()=>$('#rosterTableContainer').removeClass('hr-table-loading'));}
 $('#rosterSearch').on('input',()=>{clearTimeout(rosterTimer);rosterTimer=setTimeout(()=>loadRoster(1),350)});$('#rosterDepartment').on('change',()=>loadRoster(1));$('#rosterReset').on('click',function(){$('#rosterSearch').val('');HrUi.resetSelect('rosterDepartment');weekPicker.setDate(new Date(),true);});$(document).on('click','#rosterTableContainer .report-page-link:not(.disabled)',function(e){e.preventDefault();const u=new URL(this.href);loadRoster(u.searchParams.get('page')||1)});$(document).on('change','.roster-select',function(){$(this).closest('tr').addClass('attendance-row-dirty')});
 $('#saveRosterBtn').on('click',function(){const rows=[];$('#rosterTableContainer tbody tr[data-employee-id]').each(function(){const r=$(this),assignments=[];r.find('.roster-select').each(function(){assignments.push({date:$(this).data('date'),value:$(this).val()})});rows.push({employee_id:r.data('employee-id'),assignments})});if(!rows.length)return Swal.fire('No records','No employee records are visible.','info');const btn=$(this).prop('disabled',true);$.ajax({url:"{{ route('hr.shifts.roster.save') }}",type:'POST',contentType:'application/json',data:JSON.stringify({_token:"{{ csrf_token() }}",week_start:$('#rosterWeekStart').val(),rows})}).done(res=>{showToast('Saved',res.message);loadRoster(rosterPage)}).fail(xhr=>Swal.fire('Could not save',xhr.responseJSON?.message||'Failed.','error')).always(()=>btn.prop('disabled',false));});
 $('#copyRosterBtn').on('click',function(){Swal.fire({title:'Copy previous week?',text:'Existing entries in the selected week will be overwritten where previous entries exist.',icon:'question',showCancelButton:true,confirmButtonText:'Copy'}).then(r=>{if(!r.isConfirmed)return;$.post("{{ route('hr.shifts.roster.copy') }}",{_token:"{{ csrf_token() }}",week_start:$('#rosterWeekStart').val()}).done(res=>{showToast('Copied',res.message);loadRoster(1)}).fail(xhr=>Swal.fire('Could not copy',xhr.responseJSON?.message||'Failed.','error'))})});
 loadShifts();
});
</script>
@endsection
